SET max_parallel_workers_per_gather=0;
CREATE TEMP TABLE demand_rows AS SELECT g AS id FROM generate_series(1,100000) g;
ANALYZE demand_rows;
\echo Challenge r11: accurate estimate, parent stops demand early
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT * FROM demand_rows LIMIT 1;
\echo Control: same child to completion
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT * FROM demand_rows;
\echo Challenge r12: direct window straddles monthly partitions
CREATE TEMP TABLE boundary_rows(t timestamptz NOT NULL,id text) PARTITION BY RANGE(t);
CREATE TEMP TABLE boundary_sep PARTITION OF boundary_rows FOR VALUES FROM ('2026-09-01 00:00Z') TO ('2026-10-01 00:00Z');
CREATE TEMP TABLE boundary_oct PARTITION OF boundary_rows FOR VALUES FROM ('2026-10-01 00:00Z') TO ('2026-11-01 00:00Z');
CREATE TEMP TABLE boundary_nov PARTITION OF boundary_rows FOR VALUES FROM ('2026-11-01 00:00Z') TO ('2026-12-01 00:00Z');
INSERT INTO boundary_rows VALUES('2026-09-30 23:59:59Z','E1'),('2026-10-01 00:00Z','E2'),('2026-10-31 23:59:59Z','E3'),('2026-11-01 00:00Z','E4');
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT id FROM boundary_rows WHERE t>='2026-10-31 00:00Z' AND t<'2026-11-02 00:00Z';
SELECT array_agg(id ORDER BY id) AS expected_e3_e4 FROM boundary_rows WHERE t>='2026-10-31 00:00Z' AND t<'2026-11-02 00:00Z';
